    }
  },
  "files": [
    "dist",
    "workflow.mmd"
  ],
  "dependencies": {
    "@amykit/core": "^0.6.0",
    "@amykit/plugin-file-queue": "^0.6.0",
    "@amykit/workflow-pull-request": "^0.6.0"
  },
  "devDependencies": {
