}

import {
  ActionContext,
  baseBranchFor,
  Moved,
  RepoLayout,
  Store,
  WorkflowActionScope,
  WorkflowPieceContext,
} from "@amykit/core";
import type { PullRequestInput } from "@amykit/workflow-pull-request";
import type { Effect } from "./decide.js";
import { Observation, Policy } from "./observation.js";
import { EffectOutcomes } from "./outcomes.js";
import { ErrandRecord } from "./record.js";
import { Task } from "./ports/Tasks.js";
import type { configSchema, needs } from "./plugin.js";
import { branchFor, pullRequestBody, pullRequestTitle, slugFor } from "./task-file.js";
import { declinedIn, errandPrompt } from "./prompt.js";

/** What the declaration hands every piece: the mounted ports, the settings and the policy. */
type Scope = WorkflowPieceContext<typeof configSchema, Policy, typeof needs>;
type ActionScope = WorkflowActionScope<typeof configSchema, Policy, typeof needs>;
type Work = ActionContext<ErrandRecord, Observation>;

/** States where an errand is on its way somewhere, or already waiting. */
const IN_FLIGHT = ["WORKING", "PR_OPEN"];

/** Every task on the queue's directory is an errand to look at. */
export async function discover(scope: Scope): Promise<string[]> {
  return scope.ports.tasks.all().map((task) => task.id);
}

export async function observe(scope: Scope, current: ErrandRecord): Promise<Observation> {
  const task = scope.ports.tasks.get(current.id);
  if (!task) throw new Error(`the task ${current.id} is not in the tasks directory any more`);

  return {
    task,
    workable: scope.config.repos.includes(task.repo),
    inFlight: inFlightExcept(scope.ports.store, current.id),
    now: scope.ctx.now(),
  };
}

/**
 * The errand itself: the agent does it on its own branch, and what it left is
 * committed and published only when there is something to review.
 */
export async function runErrand(
  scope: ActionScope,
  work: Work,
  effect: Extract<Effect, { type: "run-errand" }>,
): Promise<void> {
  const { git, layout } = scope.checkouts;
  const outcomes = work.outcomes as EffectOutcomes;
  const { task } = work.observation;
  const slug = slugFor(task);
  await git.prepareBranch(task.repo, branchFor(slug), task.id);

  const reply = await scope.ports.agent.ask(
    errandPrompt(task, effect.finding),
    git.pathFor(task.repo, task.id),
    { workId: work.record.id, step: "run-errand" },
  );

  const at = scope.ctx.now().toISOString();
  if (reply.run.outcome !== "completed") {
    outcomes.attempt = { ok: false, output: reply.run.output, at };
    return;
  }

  // A refusal is the agent's decision, and nothing it left in the tree is
  // published. What it left is stashed under the task's id rather than
  // committed, so no branch a later errand reuses carries it.
  const declined = declinedIn(reply.text);
  if (declined) {
    outcomes.attempt = { ok: true, output: reply.run.output, at };
    outcomes.declined = declined;
    // The refusal stands even when the tree cannot be cleaned; the
    // operator is told what is still in the checkout instead.
    try {
      await git.setAside(task.repo, `amy: what the refused errand ${task.id} left behind`, task.id);
    } catch (error) {
      const said = error instanceof Error ? error.message : String(error);
      outcomes.declined = `${declined}\n\nWhat it left in the checkout could not be set aside: ${said}`;
    }
    return;
  }

  // Whether the errand left something to review is a question about
  // commits, not about refs. `prepareBranch` already created a branch,
  // and publishing it for the first time is a new remote ref whether or
  // not it carries a commit — so "the push moved something" answered
  // yes for every errand that was a question, and opened a pull request
  // with no diff in it.
  const committed = await git.commit(task.repo, `chore: ${pullRequestTitle(task).toLowerCase()}`, task.id);
  const changed = committed || (await git.commitsAhead(task.repo, baseBranchFor(layout, task.repo), task.id)) > 0;

  // Nothing to publish is a finished errand, not a failed one: pushing a
  // branch that carries no commit only creates a pull request nobody can
  // act on.
  if (changed) await git.push(task.repo, branchFor(slug), task.id);

  outcomes.attempt = { ok: true, output: reply.run.output, at };
  outcomes.changed = changed;
}

/** Folds what the actions produced, and what the call at `PR_OPEN` is opened with. */
export function remember(
  scope: Scope,
  current: ErrandRecord,
  outcomes: Record<string, unknown>,
  observation: Observation,
  moved: Moved | null,
): ErrandRecord {
  const bag = outcomes as EffectOutcomes;
  const next: ErrandRecord = {
    ...current,
    repo: current.repo ?? observation.task.repo,
    slug: current.slug ?? slugFor(observation.task),
    ...(bag.attempt ? { lastAttempt: bag.attempt } : {}),
    ...(bag.changed === undefined ? {} : { changed: bag.changed }),
    ...(bag.declined === undefined ? {} : { declined: bag.declined }),
  };
  // The call's input is read off the record, and the body carries what
  // the agent said, so it is worked out on the move that makes the call.
  return moved?.to === "PR_OPEN"
    ? { ...next, opening: openingFor(observation.task, next, scope.checkouts.layout), asked: observation.task.text }
    : next;
}

/** What the pull request for an errand is opened with. */
function openingFor(task: Task, record: ErrandRecord, layout: RepoLayout): PullRequestInput {
  return {
    repo: task.repo,
    branch: branchFor(slugFor(task)),
    title: pullRequestTitle(task),
    base: baseBranchFor(layout, task.repo),
    body: pullRequestBody(task, record.lastAttempt?.output ?? ""),
  };
}

/** How many other errands are on their way somewhere right now. */
function inFlightExcept(records: Store<ErrandRecord>, exceptId: string): number {
  return records.all().filter((one) => one.id !== exceptId && IN_FLIGHT.includes(one.state)).length;
}

import { Plan, act, advance, attemptsIn, looksIn, settled, wait } from "@amykit/core";
import { Observation, Policy } from "./observation.js";
import { ErrandRecord } from "./record.js";

export type ErrandState = "QUEUED" | "WORKING" | "PR_OPEN" | "DONE" | "DECLINED";
export type Effect =
  | { type: "run-errand"; finding?: string }
  | { type: "announce"; text: string };

type Decision = (record: ErrandRecord, observation: Observation, policy: Policy) => Plan;

// `PR_OPEN` is a call: the pull-request workflow decides it, and the end it
// reaches says where the errand goes.
export const decide = {
  QUEUED: planQueued,
  WORKING: planWorking,
  DONE: () => settled("the errand is done, and whoever asked was told"),
  DECLINED: () => settled("nothing was done, and the operator was told why"),
} satisfies Record<Exclude<ErrandState, "PR_OPEN">, Decision>;

/**
 * Decides the single next move for one task.
 *
 * Pure, and short: an errand is the simplest thing this machine does. What
 * makes it worth a workflow rather than a script is the two ends — a ceiling
 * on how many it may have in flight, and the fact that "it was a question,
 * not a change" is a finished errand rather than a failed one.
 */
export function plan(record: ErrandRecord, obs: Observation, policy: Policy): Plan {
  if (record.state === "PR_OPEN") throw new Error("`PR_OPEN` is a call, decided by the pull-request workflow it calls");
  return decide[record.state](record, obs, policy);
}

function planQueued(record: ErrandRecord, obs: Observation, policy: Policy): Plan {
  // A task about a repository this install does not work in is not a failure
  // and is not retried: nothing about waiting would make it workable.
  if (!obs.workable) {
    return advance("DECLINED", `${obs.task.repo} is not a repository I work in`, {
      type: "announce",
      text:
        `Somebody asked for this in ${obs.task.repo}, which I do not work in. ` +
        `It is yours: ${obs.task.text}`,
    });
  }

  // Held before an agent is spent rather than before the pull request is
  // opened. `amy btw` is meant to cost nothing, and the failure that follows
  // from that is a pile of open pull requests nobody asked to review.
  if (obs.inFlight >= policy.maxInFlight) {
    const firstLook = looksIn(record, "QUEUED") === 0;
    return wait(
      policy.ceilingBackoffMs,
      `${obs.inFlight} errand(s) are already in flight`,
      ...(firstLook
        ? ([
            {
              type: "announce" as const,
              text:
                `I am holding an errand: ${obs.inFlight} of mine are already in flight ` +
                `and nobody has looked at them. Land one and I will pick this up.\n\n` +
                `Waiting: ${obs.task.text}`,
            },
          ] as const)
        : []),
    );
  }

  return advance("WORKING", "the task is about a repository I work in");
}

function planWorking(record: ErrandRecord, obs: Observation, policy: Policy): Plan {
  // Said no, in its own words: another attempt would ask the same question
  // and spend an agent to hear the same answer.
  if (record.declined) {
    return advance("DECLINED", "the agent said it cannot be done as asked", {
      type: "announce",
      text: `I did not do this:\n\n${obs.task.text}\n\n${record.declined}`,
    });
  }

  if (record.lastAttempt?.ok) {
    // An errand that answered a question rather than changing a file is
    // finished. Treating a clean tree as a failure is what would make this
    // useless for half of what people say in passing.
    if (!record.changed) {
      return advance("DONE", "the errand was a question, and it has an answer", {
        type: "announce",
        text: `Done, and it changed nothing:\n\n${obs.task.text}\n\n${record.lastAttempt.output}`,
      });
    }
    return advance("PR_OPEN", "the errand changed something, so it needs a pull request");
  }

  const attempts = attemptsIn(record, "WORKING");
  if (attempts >= policy.maxAttempts) {
    return advance("DECLINED", `${attempts} attempt(s) did not get it done`, {
      type: "announce",
      text:
        `I could not do this across ${attempts} attempt(s):\n\n${obs.task.text}\n\n` +
        `The last thing it said:\n${record.lastAttempt?.output ?? "nothing"}`,
    });
  }

  return act(`attempt ${attempts + 1}`, {
    type: "run-errand",
    finding: record.lastAttempt?.ok === false ? record.lastAttempt.output : undefined,
  });
}

export type { Effect, ErrandState } from "./decide.js";

export { attemptsIn, looksIn } from "@amykit/core";
export type { AttemptOutcome, ErrandRecord } from "./record.js";

export { DEFAULT_POLICY } from "./observation.js";
export type { Observation, Policy } from "./observation.js";

export { branchFor, pullRequestBody, pullRequestTitle, slugFor, writeTaskFile } from "./task-file.js";
export { errandPrompt } from "./prompt.js";

export { act, advance, settled, wait } from "@amykit/core";

export { applyErrandPlan, applyOutcomes } from "./outcomes.js";
export type { EffectOutcomes } from "./outcomes.js";

export { decide, plan } from "./decide.js";

export { configSchema, plugin } from "./plugin.js";

export type { NewTask, Task, Tasks } from "./ports/Tasks.js";

import { Task } from "./ports/Tasks.js";

/**
 * A snapshot of the outside world for one task, gathered before deciding.
 *
 * The decision function reads nothing else, so a test can put the machine in
 * any situation by building one of these.
 */
export interface Observation {
  task: Task;
  /** Whether the task is about a repository this install works in. */
  workable: boolean;
  /**
   * Errands already in flight, across every repository.
   *
   * One pile rather than one per repository, because what is being rationed
   * is the reader's attention and they only have one.
   */
  inFlight: number;
  now: Date;
}

export interface Policy {
  /** How many times an agent may try one errand before it is handed back. */
  maxAttempts: number;
  /**
   * How many errands this machine may have in flight at once.
   *
   * The point of `amy btw` is that capturing costs nothing, and the failure
   * that follows from that is thirty open pull requests nobody asked to
   * review. The ceiling is what keeps a cheap capture from becoming an
   * expensive pile.
   */
  maxInFlight: number;
  /** How long to hold while the ceiling is reached. */
  ceilingBackoffMs: number;
}

export const DEFAULT_POLICY: Policy = {
  maxAttempts: 2,
  maxInFlight: 3,
  ceilingBackoffMs: 30 * 60 * 1000,
};

import { Plan, applyPlan } from "@amykit/core";
import { Observation } from "./observation.js";
import { AttemptOutcome, ErrandRecord } from "./record.js";

/** What this workflow's handlers leave behind for its own fold to read. */
export interface EffectOutcomes {
  attempt?: AttemptOutcome;
  changed?: boolean;
  declined?: string;
}

/**
 * Folds what the actions produced into the record.
 *
 * The engine has already folded the state, the attempt count and the history.
 * It cannot fold this, because it does not know what an attempt is.
 */
export function applyOutcomes(
  record: ErrandRecord,
  outcomes: EffectOutcomes,
  observation: Observation,
): ErrandRecord {
  return {
    ...record,
    repo: record.repo ?? observation.task.repo,
    ...(outcomes.attempt ? { lastAttempt: outcomes.attempt } : {}),
    ...(outcomes.changed === undefined ? {} : { changed: outcomes.changed }),
    ...(outcomes.declined === undefined ? {} : { declined: outcomes.declined }),
  };
}

/** The engine's fold and this workflow's, in the order they have to happen. */
export function applyErrandPlan(
  record: ErrandRecord,
  plan: Plan,
  outcomes: EffectOutcomes,
  observation: Observation,
  now: Date,
): ErrandRecord {
  return applyOutcomes(applyPlan(record, plan, now, outcomes), outcomes, observation);
}

import path from "node:path";
import { FileQueue } from "@amykit/plugin-file-queue";
import {
  BRANCH_SETTINGS,
  ConfigOf,
  ConfigSchema,
  Harness,
  Notifier,
  PluginCommand,
  Store,
  Worktree,
  call,
  defineWorkflow,
  optional,
  port,
} from "@amykit/core";
import { plugin as pullRequest } from "@amykit/workflow-pull-request";
import { Effect, decide } from "./decide.js";
import { DEFAULT_POLICY } from "./observation.js";
import { ErrandRecord } from "./record.js";
import { Tasks } from "./ports/Tasks.js";
import { discover, observe, remember, runErrand } from "./actions.js";
import { branchFor, writeTaskFile } from "./task-file.js";

export const configSchema = {
  repos: {
    type: "string[]",
    description:
      "where an errand may be done. The machine's own list of repositories names this by default, and a profile narrows or widens it. An errand about a place not on the list is handed back to whoever asked",
    default: [],
  },
  ...BRANCH_SETTINGS,
  tasksDirectory: {
    type: "string",
    description: "where this machine keeps the tasks `amy btw` writes, relative to the state root. The host sets it; a value here only stands in for one",
    default: "tasks",
  },
  queueDirectory: {
    type: "string",
    description: "where this machine keeps the queue `amy btw` puts the task on, relative to the state root. The host sets it; a value here only stands in for one",
    default: "queue",
  },
  "policy.maxAttempts": {
    type: "number",
    default: 2,
    description: "how many times an agent may try one errand before it is handed back",
  },
  "policy.maxInFlight": {
    type: "number",
    default: 3,
    description:
      "how many errands this machine may carry in flight at once. Capturing costs nothing, which is the whole point and also the failure, and past this many it holds rather than opening another pull request nobody asked to review",
  },
  "policy.ceilingBackoffMs": {
    type: "number",
    default: 30 * 60 * 1000,
    description: "how long a task is held while the in-flight ceiling is reached",
  },
} satisfies ConfigSchema;

type Settings = ConfigOf<typeof configSchema>;

/**
 * Something to do, said in passing.
 *
 * The shortest road into this machine, and the one command that has to work
 * on a machine that will not mount: it writes a file and puts it on the
 * queue, and nothing else is asked of it. Owning it here rather than in the
 * host is what stops every install carrying a verb only this workflow can
 * honour.
 */
const btw: PluginCommand<Settings> = {
  name: "btw",
  description: "Something to do, said in passing. Goes on the queue, never becomes a ticket",
  args: [{ name: "text", description: "what to do, in your own words" }],
  flags: [
    { flags: "--repo <owner/name>", description: "the repository it is in" },
    { flags: "--source <who>", description: "who asked", default: "somebody at a keyboard" },
  ],
  run({ home, settings, args, options, out }) {
    const repo = (options.repo as string | undefined) ?? settings.repos[0];
    if (!repo) {
      out.error("no repository: pass --repo, or list one under `repos`.");
      process.exitCode = 1;
      return;
    }

    const now = new Date();
    const text = args[0] ?? "";
    const task = writeTaskFile(
      path.join(home, settings.tasksDirectory),
      { repo, text, source: String(options.source ?? "somebody at a keyboard") },
      now,
    );
    new FileQueue(path.join(home, settings.queueDirectory)).enqueue({ workId: task.id, reason: "said in passing" }, now);

    out.line(`noted ${task.id} in ${repo}`);
  },
};

export const needs = {
  tasks: port<Tasks>(),
  agent: port<Harness>(),
  notifier: port<Notifier>(),
  store: port<Store<ErrandRecord>>(),
  worktree: optional<Worktree>(),
};

/**
 * An errand saved in `PR_OPEN` before it was a call worked out nothing to
 * pass, so it is opened with what its record still says, against the host's
 * default.
 */
function openingAfterUpgrade(work: ErrandRecord) {
  return { repo: work.repo ?? "", branch: branchFor(work.slug ?? work.id), title: work.slug ?? work.id, body: work.lastAttempt?.output ?? "" };
}

export const plugin = defineWorkflow({
  name: "errand",
  pluginName: "@amykit/workflow-errand",
  configSchema,
  policy: DEFAULT_POLICY,
  needs,
  // A project is brief, work and proof; an errand is the work half alone.
  // Said in passing, its own words are the brief, and it is a person who
  // looks at the draft it opens — so no brief phase and no proving phase.
  phases: {
    brief: "an errand is said in passing: the note itself says what to do, so there is no brief phase to run first",
    prove: "an errand opens a draft pull request on purpose, and the person who asked reads it; the work runs no separate proving phase",
  },
  codeHostWrites: ["open-pull-request"],
  calls: {
    // A draft, because nobody asked for this at the moment it landed. Work
    // somebody is waiting on is not a draft; an errand is something to look
    // at when you want to.
    PR_OPEN: call(pullRequest, {
      input: (work: ErrandRecord) => work.opening ?? openingAfterUpgrade(work),
      config: { draft: true },
      output: {
        OPENED: (work: ErrandRecord, out) => ({ ...work, pullRequestNumber: out.number, pullRequestUrl: out.url }),
        REFUSED: (work: ErrandRecord, out) => ({ ...work, refusal: out.reason }),
      },
      effects: {
        // The link, not the number. This is read on a phone more often than
        // anywhere else, and a number is something you have to go and look up.
        OPENED: (work: ErrandRecord, out) => [{
          type: "announce",
          text: `Done, and it is a draft for you to look at:\n\n${work.asked ?? work.slug ?? work.id}\n\n${out.url}`,
        }],
        REFUSED: (work: ErrandRecord, out) => [{
          type: "announce",
          text:
            `I did this, and the code host would not open a pull request for it:\n\n${work.asked ?? work.slug ?? work.id}\n\n` +
            `${out.reason}\n\nThe branch is \`${work.opening?.branch ?? "unknown"}\`.`,
        }],
      },
    }),
  },
  decide,
  commands: [btw],
  record: () => ({}),
  discover,
  observe,
  actions: {
    "run-errand": runErrand,
    // Only worth saying, so a channel that fails never costs the work a move.
    announce: (scope, _work, effect) => scope.announce((effect as Extract<Effect, { type: "announce" }>).text),
  },
  remember,
});

/**
 * Something to do, said in passing.
 *
 * The opposite of a note: a note is friction that happened and becomes a
 * plan, and a task is work somebody wants done. Neither is a ticket, and the
 * difference from a ticket is that nobody had to open one — the cost of
 * capturing it has to be close to zero or it does not get captured at all.
 */
export interface Task {
  /** Sortable, so the tasks have a stable order without an index. */
  id: string;
  /** The repository the work is in, as `owner/name`. */
  repo: string;
  /** What to do, in the words of whoever asked. */
  text: string;
  /** Who asked: a person at a keyboard, or an agent mid-conversation. */
  source: string;
  addedAt: string;
}

/** A task as it is written, before anything has been decided about it. */
export type NewTask = Omit<Task, "id" | "addedAt">;

/**
 * Where the tasks are kept.
 *
 * Two ways in and one way out, the same shape the notes have: `amy btw`
 * writes one, an editor or a hook can write one, and `all()` is what the
 * workflow discovers work from.
 */
export interface Tasks {
  add(task: NewTask, now: Date): Task;
  all(): Task[];
  get(id: string): Task | null;
}

import { Task } from "./ports/Tasks.js";

/**
 * What the agent is asked, in the words of whoever asked it.
 *
 * Deliberately thin. The task text is somebody's own sentence and the
 * temptation is to decorate it into a specification; what that produces is an
 * agent answering the decoration. What it needs around it is the two things
 * the sentence does not carry: where it is, and what to do when the sentence
 * turns out to be wrong.
 */
export function errandPrompt(task: Task, finding?: string): string {
  return [
    `Somebody asked for this in passing, and it was never a ticket:`,
    ``,
    task.text.trim(),
    ``,
    `You are in a checkout of ${task.repo}, on a branch of your own.`,
    ``,
    `Do it if it is a change: make it, and leave the working tree with the`,
    `change in it. Say in one paragraph what you did.`,
    ``,
    `If it turns out to be a question rather than a change, answer it and`,
    `change nothing. An errand that ends in a sentence is finished, not failed.`,
    ``,
    `If it cannot be done as asked — it is already done, it is wrong, or it`,
    `needs a decision nobody made — say so plainly and change nothing. Do not`,
    `do a different, easier thing instead. Then end your reply with this line,`,
    `and write it for nothing else:`,
    ``,
    `${JSON.stringify({ declined: "why, in one sentence" })}`,
    ...(finding
      ? [``, `Your last attempt did not get through. What came back:`, ``, finding]
      : []),
  ].join("\n");
}

/**
 * The reason on the line the prompt asks a refusal to end with, if there is one.
 *
 * Read off the last line only, so an answer that quotes JSON is not mistaken
 * for a refusal, and an answer with no such line is an answer.
 */
export function declinedIn(reply: string): string | undefined {
  const last = reply.trim().split("\n").at(-1)?.trim() ?? "";
  if (!last.startsWith("{")) return undefined;
  try {
    const parsed: unknown = JSON.parse(last);
    const declined = (parsed as { declined?: unknown } | null)?.declined;
    return typeof declined === "string" && declined.trim() ? declined.trim() : undefined;
  } catch {
    return undefined;
  }
}

import { WorkRecord } from "@amykit/core";
import type { PullRequestInput } from "@amykit/workflow-pull-request";
import type { ErrandState } from "./decide.js";

export interface AttemptOutcome {
  ok: boolean;
  /** Whatever the agent said, verbatim, for the next prompt or the report. */
  output: string;
  at: string;
}

/**
 * Everything the machine remembers about one task, between looks.
 *
 * `repo` and `slug` are copied off the task on the first look rather than
 * read from it every time, because the ceiling is counted across *other*
 * records without opening every task to find out what each one was about.
 */
export interface ErrandRecord extends WorkRecord {
  /** Narrowed from the core's plain label to this workflow's own states. */
  state: ErrandState;
  repo?: string;
  /** The name the branch takes. */
  slug?: string;
  lastAttempt?: AttemptOutcome;
  /**
   * Whether the last attempt left a change on a branch.
   *
   * False is a real answer rather than a failure: "check whether the monitor
   * is still firing" is an errand that ends in a sentence, not a diff.
   */
  changed?: boolean;
  /** Why the agent said it would not do this, which no retry changes. */
  declined?: string;
  /** What the pull request is opened with, worked out when the errand reaches `PR_OPEN`: its call is passed this. */
  opening?: PullRequestInput;
  pullRequestNumber?: number;
  pullRequestUrl?: string;
  /** What the code host said when it would not open the pull request. */
  refusal?: string;
  /** What was asked, kept when the errand reaches `PR_OPEN` so the edge out of the call can say it. */
  asked?: string;
}

import fs from "node:fs";
import path from "node:path";
import { NewTask, Task } from "./ports/Tasks.js";

/** How many words of the task become the branch name. */
const WORDS = 6;

/**
 * A branch name from what somebody typed.
 *
 * Derived rather than asked for: the whole promise of `amy btw` is that
 * capturing costs one sentence, and a prompt for a branch name is the
 * ceremony that stops people using it.
 */
export function slugFor(task: Task): string {
  const words = task.text
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, WORDS);

  return words.length > 0 ? words.join("-") : task.id;
}

export function branchFor(slug: string): string {
  return `amy/errand-${slug}`;
}

export function pullRequestTitle(task: Task): string {
  const first = task.text.trim().split("\n")[0] ?? "";
  return first.length > 72 ? `${first.slice(0, 69)}...` : first;
}

/**
 * The description, written out.
 *
 * There is no ticket behind an errand to be the description, so the body has
 * to carry what a reviewer would otherwise have to ask for: what was asked,
 * by whom, and that a machine did it.
 */
export function pullRequestBody(task: Task, said: string): string {
  return [
    `**Asked for by ${task.source}**, ${task.addedAt}:`,
    ``,
    `> ${task.text.trim().split("\n").join("\n> ")}`,
    ``,
    `---`,
    ``,
    said.trim() || "The agent left no account of what it did.",
    ``,
    `This was an errand — captured with \`amy btw\`, never a ticket.`,
  ].join("\n");
}

/**
 * A task, as the file an editor or a hook would leave.
 *
 * Written here rather than in the store adapter because `amy btw` writes it
 * on a machine that will not mount: both callers share one format, and the
 * workflow that reads the directory is the one that owns its vocabulary.
 */
export function writeTaskFile(directory: string, task: NewTask, now: Date): Task {
  fs.mkdirSync(directory, { recursive: true });
  const written: Task = { ...task, id: freeTaskId(directory, now), addedAt: now.toISOString() };
  fs.writeFileSync(path.join(directory, `${written.id}.md`), taskMarkdown(written), "utf-8");
  return written;
}

function taskMarkdown(task: Task): string {
  return ["---", `repo: ${task.repo}`, `source: ${task.source}`, `added: ${task.addedAt}`, "---", "", task.text.trim(), ""].join("\n");
}

function freeTaskId(directory: string, now: Date): string {
  const stamp = `task-${now.toISOString().replace(/[:.]/g, "").replace("Z", "")}`;
  const taken = (id: string) => fs.existsSync(path.join(directory, `${id}.md`));
  if (!taken(stamp)) return stamp;
  for (let n = 2; ; n += 1) {
    if (!taken(`${stamp}-${n}`)) return `${stamp}-${n}`;
  }
}
